"use client";

import { useForm } from "@tanstack/react-form";
import {
  Alert,
  AlertDescription,
  AlertTitle,
} from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Field,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Loader } from "@/components/ui/loader";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { useId, useState } from "react";
import { z } from "zod";

export interface BugReportValues {
  title: string;
  description: string;
}
export interface ProfileValues {
  name: string;
  email: string;
  role: string;
  notifications: boolean;
}
/** Text shared by form feedback and submission controls. */
export interface FormFeedbackLabels {
  failed: string;
  saved: string;
  savedDescription: string;
  submitError: string;
  submitting: string;
  reset: string;
}

const defaultFormFeedbackLabels: FormFeedbackLabels = {
  failed: "Submission failed",
  saved: "Saved",
  savedDescription: "Your changes have been submitted.",
  submitError: "Please try again.",
  submitting: "Submitting…",
  reset: "Reset",
};

export interface BugReportFormLabels extends FormFeedbackLabels {
  formTitle: string;
  formDescription: string;
  title: string;
  titlePlaceholder: string;
  description: string;
  descriptionHint: string;
  titleMinLength: string;
  titleMaxLength: string;
  descriptionMinLength: string;
  descriptionMaxLength: string;
  submit: string;
}

export const defaultBugReportFormLabels: BugReportFormLabels = {
  ...defaultFormFeedbackLabels,
  formTitle: "Bug report",
  formDescription: "Tell us what happened so we can improve the product.",
  title: "Title",
  titlePlaceholder: "Login button does not work on mobile",
  description: "Description",
  descriptionHint:
    "Include steps to reproduce, expected behavior, and actual results.",
  titleMinLength: "Title must be at least 5 characters.",
  titleMaxLength: "Title must be at most 80 characters.",
  descriptionMinLength: "Description must be at least 20 characters.",
  descriptionMaxLength: "Description must be at most 500 characters.",
  submit: "Submit report",
};

export interface ProfileFormLabels extends FormFeedbackLabels {
  formTitle: string;
  formDescription: string;
  name: string;
  email: string;
  role: string;
  rolePlaceholder: string;
  designerRole: string;
  developerRole: string;
  managerRole: string;
  notifications: string;
  nameMinLength: string;
  nameMaxLength: string;
  invalidEmail: string;
  invalidRole: string;
  submit: string;
}

export const defaultProfileFormLabels: ProfileFormLabels = {
  ...defaultFormFeedbackLabels,
  formTitle: "Profile settings",
  formDescription: "Update your details and notification preferences.",
  name: "Name",
  email: "Email",
  role: "Role",
  rolePlaceholder: "Choose a role",
  designerRole: "Designer",
  developerRole: "Developer",
  managerRole: "Manager",
  notifications: "Email me product updates",
  nameMinLength: "Name must be at least 2 characters.",
  nameMaxLength: "Name must be at most 50 characters.",
  invalidEmail: "Enter a valid email address.",
  invalidRole: "Choose a role.",
  submit: "Save profile",
};

export interface FormBlockProps<T, TLabels = FormFeedbackLabels> {
  initialValues?: Partial<T>;
  onSubmit: (values: T) => void | Promise<void>;
  labels?: Partial<TLabels>;
  className?: string;
}

function useSubmission<T>(
  onSubmit: FormBlockProps<T>["onSubmit"],
  fallback: string,
) {
  const [feedback, setFeedback] = useState<{ error?: string; saved?: boolean }>(
    {},
  );
  async function submit(values: T) {
    setFeedback({});
    try {
      await onSubmit(values);
      setFeedback({ saved: true });
    } catch (error) {
      setFeedback({ error: error instanceof Error ? error.message : fallback });
    }
  }
  return { feedback, submit, reset: () => setFeedback({}) };
}

function FormFeedback({
  feedback,
  labels,
}: {
  feedback: { error?: string; saved?: boolean };
  labels: FormFeedbackLabels;
}) {
  if (!feedback.error && !feedback.saved) return null;
  return (
    <Alert
      variant={feedback.error ? "destructive" : "default"}
      role={feedback.error ? "alert" : "status"}
    >
      <AlertTitle>{feedback.error ? labels.failed : labels.saved}</AlertTitle>
      <AlertDescription>
        {feedback.error ?? labels.savedDescription}
      </AlertDescription>
    </Alert>
  );
}

/** A validated report form with asynchronous submission and reset controls. */
export function BugReportForm({
  initialValues,
  onSubmit,
  labels: overrides,
  className,
}: FormBlockProps<BugReportValues, BugReportFormLabels>) {
  const labels = { ...defaultBugReportFormLabels, ...overrides };
  const id = useId();
  const schema = z.object({
    title: z
      .string()
      .trim()
      .min(5, labels.titleMinLength)
      .max(80, labels.titleMaxLength),
    description: z
      .string()
      .trim()
      .min(20, labels.descriptionMinLength)
      .max(500, labels.descriptionMaxLength),
  });
  const submission = useSubmission(onSubmit, labels.submitError);
  const form = useForm({
    defaultValues: { title: "", description: "", ...initialValues },
    validators: { onBlur: schema, onSubmit: schema },
    onSubmit: async ({ value }) => submission.submit(schema.parse(value)),
  });
  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>{labels.formTitle}</CardTitle>
        <CardDescription>{labels.formDescription}</CardDescription>
      </CardHeader>
      <CardContent>
        <form
          id={id}
          noValidate
          onSubmit={(event) => {
            event.preventDefault();
            void form.handleSubmit();
          }}
        >
          <form.Subscribe selector={(state) => state.isSubmitting}>
            {(pending) => (
              <FieldGroup>
                <form.Field name="title">
                  {(field) => {
                    const invalid =
                      field.state.meta.isTouched && !field.state.meta.isValid;
                    return (
                      <Field data-invalid={invalid} data-disabled={pending}>
                        <FieldLabel htmlFor={`${id}-title`}>
                          {labels.title}
                        </FieldLabel>
                        <Input
                          id={`${id}-title`}
                          name={field.name}
                          value={field.state.value}
                          disabled={pending}
                          onBlur={field.handleBlur}
                          onChange={(event) =>
                            field.handleChange(event.target.value)
                          }
                          aria-invalid={invalid}
                          aria-describedby={
                            invalid ? `${id}-title-error` : undefined
                          }
                          placeholder={labels.titlePlaceholder}
                          autoComplete="off"
                        />
                        {invalid && (
                          <FieldError
                            id={`${id}-title-error`}
                            errors={field.state.meta.errors}
                          />
                        )}
                      </Field>
                    );
                  }}
                </form.Field>
                <form.Field name="description">
                  {(field) => {
                    const invalid =
                      field.state.meta.isTouched && !field.state.meta.isValid;
                    return (
                      <Field data-invalid={invalid} data-disabled={pending}>
                        <FieldLabel htmlFor={`${id}-description`}>
                          {labels.description}
                        </FieldLabel>
                        <Textarea
                          id={`${id}-description`}
                          name={field.name}
                          value={field.state.value}
                          rows={5}
                          disabled={pending}
                          onBlur={field.handleBlur}
                          onChange={(event) =>
                            field.handleChange(event.target.value)
                          }
                          aria-invalid={invalid}
                          aria-describedby={`${id}-description-hint${invalid ? ` ${id}-description-error` : ""}`}
                        />
                        <FieldDescription id={`${id}-description-hint`}>
                          {labels.descriptionHint}
                        </FieldDescription>
                        {invalid && (
                          <FieldError
                            id={`${id}-description-error`}
                            errors={field.state.meta.errors}
                          />
                        )}
                      </Field>
                    );
                  }}
                </form.Field>
                <FormFeedback feedback={submission.feedback} labels={labels} />
              </FieldGroup>
            )}
          </form.Subscribe>
        </form>
      </CardContent>
      <CardFooter>
        <form.Subscribe
          selector={(state) => [state.canSubmit, state.isSubmitting] as const}
        >
          {([canSubmit, pending]) => (
            <Field orientation="horizontal">
              <Button
                type="button"
                variant="outline"
                disabled={pending}
                onClick={() => {
                  form.reset();
                  submission.reset();
                }}
              >
                {labels.reset}
              </Button>
              <Button type="submit" form={id} disabled={!canSubmit || pending}>
                {pending && <Loader size="sm" label={labels.submitting} />}
                {labels.submit}
              </Button>
            </Field>
          )}
        </form.Subscribe>
      </CardFooter>
    </Card>
  );
}

/** Combines text, email, select, and checkbox fields using TanStack Form. */
export function ProfileForm({
  initialValues,
  onSubmit,
  labels: overrides,
  className,
}: FormBlockProps<ProfileValues, ProfileFormLabels>) {
  const labels = { ...defaultProfileFormLabels, ...overrides };
  const id = useId();
  const roles = [
    { value: "designer", label: labels.designerRole },
    { value: "developer", label: labels.developerRole },
    { value: "manager", label: labels.managerRole },
  ];
  const schema = z.object({
    name: z
      .string()
      .trim()
      .min(2, labels.nameMinLength)
      .max(50, labels.nameMaxLength),
    email: z.email(labels.invalidEmail),
    role: z.enum(["designer", "developer", "manager"], {
      error: labels.invalidRole,
    }),
    notifications: z.boolean(),
  });
  const submission = useSubmission(onSubmit, labels.submitError);
  const form = useForm({
    defaultValues: {
      name: "",
      email: "",
      role: "",
      notifications: true,
      ...initialValues,
    },
    validators: { onBlur: schema, onSubmit: schema },
    onSubmit: async ({ value }) => submission.submit(schema.parse(value)),
  });
  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>{labels.formTitle}</CardTitle>
        <CardDescription>{labels.formDescription}</CardDescription>
      </CardHeader>
      <CardContent>
        <form
          id={id}
          noValidate
          onSubmit={(event) => {
            event.preventDefault();
            void form.handleSubmit();
          }}
        >
          <form.Subscribe selector={(state) => state.isSubmitting}>
            {(pending) => (
              <FieldGroup>
                {(["name", "email"] as const).map((name) => (
                  <form.Field key={name} name={name}>
                    {(field) => {
                      const invalid =
                        field.state.meta.isTouched && !field.state.meta.isValid;
                      return (
                        <Field data-invalid={invalid} data-disabled={pending}>
                          <FieldLabel htmlFor={`${id}-${name}`}>
                            {labels[name]}
                          </FieldLabel>
                          <Input
                            id={`${id}-${name}`}
                            name={field.name}
                            type={name === "email" ? "email" : "text"}
                            autoComplete={name}
                            value={field.state.value}
                            disabled={pending}
                            onBlur={field.handleBlur}
                            onChange={(event) =>
                              field.handleChange(event.target.value)
                            }
                            aria-invalid={invalid}
                            aria-describedby={
                              invalid ? `${id}-${name}-error` : undefined
                            }
                          />
                          {invalid && (
                            <FieldError
                              id={`${id}-${name}-error`}
                              errors={field.state.meta.errors}
                            />
                          )}
                        </Field>
                      );
                    }}
                  </form.Field>
                ))}
                <form.Field name="role">
                  {(field) => {
                    const invalid =
                      field.state.meta.isTouched && !field.state.meta.isValid;
                    return (
                      <Field data-invalid={invalid} data-disabled={pending}>
                        <FieldLabel htmlFor={`${id}-role`}>
                          {labels.role}
                        </FieldLabel>
                        <Select
                          items={roles}
                          name={field.name}
                          value={field.state.value || null}
                          disabled={pending}
                          onValueChange={(value) =>
                            field.handleChange(value ?? "")
                          }
                        >
                          <SelectTrigger
                            id={`${id}-role`}
                            onBlur={field.handleBlur}
                            aria-invalid={invalid}
                            aria-describedby={
                              invalid ? `${id}-role-error` : undefined
                            }
                          >
                            <SelectValue placeholder={labels.rolePlaceholder} />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectGroup>
                              {roles.map((role) => (
                                <SelectItem key={role.value} value={role.value}>
                                  {role.label}
                                </SelectItem>
                              ))}
                            </SelectGroup>
                          </SelectContent>
                        </Select>
                        {invalid && (
                          <FieldError
                            id={`${id}-role-error`}
                            errors={field.state.meta.errors}
                          />
                        )}
                      </Field>
                    );
                  }}
                </form.Field>
                <form.Field name="notifications">
                  {(field) => (
                    <Field orientation="horizontal" data-disabled={pending}>
                      <Checkbox
                        id={`${id}-notifications`}
                        name={field.name}
                        checked={field.state.value}
                        disabled={pending}
                        onBlur={field.handleBlur}
                        onCheckedChange={field.handleChange}
                      />
                      <FieldLabel htmlFor={`${id}-notifications`}>
                        {labels.notifications}
                      </FieldLabel>
                    </Field>
                  )}
                </form.Field>
                <FormFeedback feedback={submission.feedback} labels={labels} />
              </FieldGroup>
            )}
          </form.Subscribe>
        </form>
      </CardContent>
      <CardFooter>
        <form.Subscribe
          selector={(state) => [state.canSubmit, state.isSubmitting] as const}
        >
          {([canSubmit, pending]) => (
            <Field orientation="horizontal">
              <Button
                type="button"
                variant="outline"
                disabled={pending}
                onClick={() => {
                  form.reset();
                  submission.reset();
                }}
              >
                {labels.reset}
              </Button>
              <Button type="submit" form={id} disabled={!canSubmit || pending}>
                {pending && <Loader size="sm" label={labels.submitting} />}
                {labels.submit}
              </Button>
            </Field>
          )}
        </form.Subscribe>
      </CardFooter>
    </Card>
  );
}

import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import type * as React from "react";
import { withGlass } from "@/lib/glass/context";

const alertVariants = cva(
  "group/alert relative grid w-full gap-0.5 rounded-2xl border px-4 py-3 text-start text-sm has-data-[slot=alert-action]:relative has-[>svg]:grid-cols-[auto_1fr] has-[>svg]:gap-x-2.5 has-data-[slot=alert-action]:pe-18 *:[svg:not([class*='size-'])]:size-4 *:[svg]:row-span-2 *:[svg]:translate-y-0.5 *:[svg]:text-current",
  {
    variants: {
      variant: {
        default: "bg-card text-card-foreground",
        destructive:
          "bg-card text-destructive *:data-[slot=alert-description]:text-destructive/90 *:[svg]:text-current",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

function AlertImplementation({
  className,
  variant,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof alertVariants>) {
  return (
    <div
      data-slot="alert"
      role="alert"
      className={cn(alertVariants({ variant }), className)}
      {...props}
    />
  );
}

function AlertTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-title"
      className={cn(
        "font-medium group-has-[>svg]/alert:col-start-2 [&_a]:underline [&_a]:underline-offset-3 [&_a]:hover:text-foreground",
        className,
      )}
      {...props}
    />
  );
}

function AlertDescription({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-description"
      className={cn(
        "text-balance text-muted-foreground text-sm md:text-pretty [&_a]:underline [&_a]:underline-offset-3 [&_a]:hover:text-foreground [&_p:not(:last-child)]:mb-4",
        className,
      )}
      {...props}
    />
  );
}

function AlertAction({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-action"
      className={cn("absolute end-3 top-2.5", className)}
      {...props}
    />
  );
}

const Alert = withGlass(AlertImplementation);

export { Alert, AlertAction, AlertDescription, AlertTitle };

import { Button as ButtonPrimitive } from "@base-ui/react/button";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "cn";
import { withGlass } from "@/lib/glass/context";

const buttonVariants = cva(
  "group/button inline-flex shrink-0 select-none items-center justify-center whitespace-nowrap rounded-4xl border border-transparent bg-clip-padding font-medium text-sm outline-none transition-[box-shadow,transform] focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/30 active:not-aria-[haspopup]:translate-y-px disabled:pointer-events-none disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 [&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground hover:bg-primary/80",
        outline:
          "border-border bg-background hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:bg-transparent dark:hover:bg-input/30",
        secondary:
          "bg-secondary text-secondary-foreground hover:bg-[color-mix(in_oklch,var(--secondary),var(--foreground)_5%)] aria-expanded:bg-secondary aria-expanded:text-secondary-foreground",
        ghost:
          "hover:bg-muted hover:text-foreground aria-expanded:bg-muted aria-expanded:text-foreground dark:hover:bg-muted/50",
        destructive:
          "bg-destructive/10 text-destructive hover:bg-destructive/20 focus-visible:border-destructive/40 focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:focus-visible:ring-destructive/40 dark:hover:bg-destructive/30",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default:
          "h-9 gap-1.5 px-3 has-data-[icon=inline-start]:ps-2.5 has-data-[icon=inline-end]:pe-2.5",
        xs: "h-6 gap-1 px-2.5 has-data-[icon=inline-start]:ps-2 has-data-[icon=inline-end]:pe-2 [&_svg:not([class*='size-'])]:size-3",
        sm: "h-8 gap-1 px-3 has-data-[icon=inline-start]:ps-2 has-data-[icon=inline-end]:pe-2",
        lg: "h-10 gap-1.5 px-4 has-data-[icon=inline-start]:ps-3 has-data-[icon=inline-end]:pe-3",
        icon: "size-9",
        "icon-xs": "size-6 [&_svg:not([class*='size-'])]:size-3",
        "icon-sm": "size-8",
        "icon-lg": "size-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

function ButtonImplementation({
  className,
  variant = "default",
  size = "default",
  ...props
}: ButtonPrimitive.Props & VariantProps<typeof buttonVariants>) {
  return (
    <ButtonPrimitive
      data-slot="button"
      data-variant={variant}
      className={cn(buttonVariants({ variant, size, className }))}
      {...props}
    />
  );
}

const Button = withGlass(ButtonImplementation, "control");

export { Button, buttonVariants };

import { cn } from "cn";
import type * as React from "react";
import { withGlass } from "@/lib/glass/context";

function CardImplementation({
  className,
  size = "default",
  ...props
}: React.ComponentProps<"div"> & { size?: "default" | "sm" }) {
  return (
    <div
      data-slot="card"
      data-size={size}
      className={cn(
        "group/card flex flex-col gap-(--card-spacing) overflow-hidden rounded-4xl bg-card py-(--card-spacing) text-card-foreground text-sm shadow-md ring-1 ring-foreground/5 [--card-spacing:--spacing(6)] has-[>img:first-child]:pt-0 dark:ring-foreground/10 data-[size=sm]:[--card-spacing:--spacing(4)] *:[img:first-child]:rounded-t-4xl *:[img:last-child]:rounded-b-4xl",
        className,
      )}
      {...props}
    />
  );
}

function CardHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-header"
      className={cn(
        "group/card-header @container/card-header grid auto-rows-min items-start gap-1.5 rounded-t-4xl px-(--card-spacing) has-data-[slot=card-action]:grid-cols-[1fr_auto] has-data-[slot=card-description]:grid-rows-[auto_auto] [.border-b]:pb-(--card-spacing)",
        className,
      )}
      {...props}
    />
  );
}

function CardTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-title"
      className={cn("font-heading font-medium text-base", className)}
      {...props}
    />
  );
}

function CardDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-description"
      className={cn("text-muted-foreground text-sm", className)}
      {...props}
    />
  );
}

function CardAction({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-action"
      className={cn(
        "col-start-2 row-span-2 row-start-1 self-start justify-self-end",
        className,
      )}
      {...props}
    />
  );
}

function CardContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-content"
      className={cn("px-(--card-spacing)", className)}
      {...props}
    />
  );
}

function CardFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="card-footer"
      className={cn(
        "flex items-center rounded-b-4xl px-(--card-spacing) [.border-t]:pt-(--card-spacing)",
        className,
      )}
      {...props}
    />
  );
}

const Card = withGlass(CardImplementation);

export {
  Card,
  CardAction,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
};

"use client";

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";
import { cn } from "cn";
import { CheckIcon } from "lucide-react";
import { withGlass } from "@/lib/glass/context";

function CheckboxImplementation({
  className,
  ...props
}: CheckboxPrimitive.Root.Props) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(
        "peer relative flex size-4 shrink-0 items-center justify-center rounded-[5px] border border-transparent bg-input/90 outline-none transition-shadow after:absolute after:-inset-x-3 after:-inset-y-2 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/30 disabled:cursor-not-allowed disabled:opacity-50 group-has-[:focus-visible]/field-label:not-data-checked:border-transparent group-has-disabled/field:opacity-50 group-has-[:focus-visible]/field-label:ring-0 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 aria-invalid:aria-checked:border-primary data-checked:border-primary data-checked:bg-primary data-checked:text-primary-foreground group-has-[:focus-visible]/field-label:data-checked:border-primary dark:data-checked:bg-primary dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="grid place-content-center text-current transition-none [&>svg]:size-3.5"
      >
        <CheckIcon />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}

const Checkbox = withGlass(CheckboxImplementation, "control");

export { Checkbox };

