    }
  });
  return `${sheets.join("|")}|${Array.from(families).sort().join("|")}|${target.ownerDocument.fonts?.status}|${version.value}`;
}

async function embeddedFonts(target: HTMLElement) {
  const key = fontKey(target);
  const fontCache = fontVersion(target.ownerDocument).cache;
  let cached = fontCache.get(target);
  if (cached?.key !== key) {
    const { getFontEmbedCSS } = await loadLibrary();
    const css = sample(
      getFontEmbedCSS(target, { preferredFontFormat: "woff2" }),
      4000,
    );
    cached = { key, css };
    fontCache.set(target, cached);
    css.catch(() => {
      if (fontCache.get(target)?.css === css) fontCache.delete(target);
    });
  }
  return cached.css;
}

async function imageReadiness(target: HTMLElement, blocked: Set<Element>) {
  const images = [
    ...(target.matches("img") ? [target as HTMLImageElement] : []),
    ...target.querySelectorAll<HTMLImageElement>("img"),
  ];
  await Promise.all(
    images.map(async (image) => {
      if (!included(image, blocked) || !image.getAttribute("src")) return;
      if (!image.complete) await bounded(image.decode(), 3000);
      if (!image.naturalWidth)
        throw new Error("Glass background contains a failed image");
    }),
  );
}

function validateResources(root: Element) {
  for (const image of root.querySelectorAll("img,image")) {
    const source =
      image.getAttribute("src") ??
      image.getAttribute("href") ??
      image.getAttribute("xlink:href");
    if (source && !source.startsWith("data:"))
      throw new Error("Glass background contains an unreadable image");
    if (source === "")
      throw new Error("Glass background image embedding failed");
  }
  const source = [root, ...root.querySelectorAll("*")]
    .map(
      (element) =>
        `${element.getAttribute("style") ?? ""}${element.localName === "style" ? element.textContent : ""}`,
    )
    .join("\n");
  for (const match of source.matchAll(
    /url\(\s*(?:"((?:\\.|[^"\\])*)"|'((?:\\.|[^'\\])*)'|([^)'"\s]*))\s*\)/g,
  )) {
    const resource = match[1] ?? match[2] ?? match[3] ?? "";
    if (
      !resource ||
      (!resource.startsWith("data:") && !resource.startsWith("#"))
    )
      throw new Error("Glass background resource embedding failed");
  }
}

async function captureBackground(
  target: HTMLElement,
  blocked: Set<Element>,
): Promise<HTMLCanvasElement> {
  if (!target.isConnected || !included(target, blocked))
    throw new Error("Glass capture target unavailable");
  const bounds = target.getBoundingClientRect();
  if (!bounds.width || !bounds.height || !axisAligned(target))
    throw new Error("Glass capture target has unsupported geometry");
  const size = glassLayoutSize(target, bounds);
  const scaleX = bounds.width / size.width;
  const scaleY = bounds.height / size.height;
  await bounded(target.ownerDocument.fonts?.ready ?? Promise.resolve(), 1500);
  await imageReadiness(target, blocked);
  const { toSvg } = await loadLibrary();
  const fontEmbedCSS = await embeddedFonts(target);
  const placements: Placement[] = [];
  let svg: string;
  try {
    prepare(target, blocked, placements);
    const options: CaptureOptions = {
      width: size.width,
      height: size.height,
      fontEmbedCSS,
      pixelRatio: 1,
      style: {
        position: "relative",
        left: "0",
        top: "0",
        margin: "0",
        width: `${size.width}px`,
        height: `${size.height}px`,
        boxSizing: "border-box",
        maxWidth: "none",
        maxHeight: "none",
        animation: "none",
        transition: "none",
        transform: "none",
        translate: "none",
        scale: "none",
        rotate: "none",
        zoom: "1",
      },
      filter: (node) =>
        !(node instanceof Element) || included(node, blocked, true),
      onImageErrorHandler: (event) => {
        const failed = typeof event === "string" ? null : event.target;
        const marked =
          failed instanceof Element ? failed.closest(`[${marker}]`) : null;
        if (
          marked &&
          placements.some(
            (item) => item.hidden && marked.getAttribute(marker) === item.id,
          )
        )
          return;
        throw new Error("Glass background image embedding failed");
      },
    };
    svg = await sample(toSvg(target, options), 6000);
  } finally {
    restore(placements);
  }
  const comma = svg.indexOf(",");
  if (comma < 0 || !svg.startsWith("data:image/svg+xml"))
    throw new Error("Invalid glass capture SVG");
  const source = svg.slice(comma + 1);
  const xml = new DOMParser().parseFromString(
    svg.slice(0, comma).includes(";base64")
      ? new TextDecoder().decode(
          Uint8Array.from(atob(source), (character) => character.charCodeAt(0)),
        )
      : decodeURIComponent(source),
    "image/svg+xml",
  );
  if (xml.querySelector("parsererror"))
    throw new Error("Invalid glass capture SVG");
  const root = xml.documentElement;
  const foreign = root.querySelector("foreignObject");
  const content = foreign?.firstElementChild;
  if (!foreign || !content) throw new Error("Glass capture content missing");
  repairClone(content, placements, target);
  validateResources(root);
  root.setAttribute("width", String(innerWidth));
  root.setAttribute("height", String(innerHeight));
  root.setAttribute("viewBox", `0 0 ${innerWidth} ${innerHeight}`);
  foreign.setAttribute(
    "x",
    scaleX === 1 && scaleY === 1 ? String(bounds.left) : "0",
  );
  foreign.setAttribute(
    "y",
    scaleX === 1 && scaleY === 1 ? String(bounds.top) : "0",
  );
  foreign.setAttribute("width", String(size.width));
  foreign.setAttribute("height", String(size.height));
  if (scaleX !== 1 || scaleY !== 1)
    foreign.setAttribute(
      "transform",
      `matrix(${scaleX} 0 0 ${scaleY} ${bounds.left} ${bounds.top})`,
    );
  const image = new Image();
  const ready = new Promise<void>((resolve, reject) => {
    image.onload = () => resolve();
    image.onerror = () =>
      reject(new Error("Glass background SVG rasterization failed"));
  });
  image.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(new XMLSerializer().serializeToString(root))}`;
  try {
    await bounded(ready, 3000);
  } finally {
    image.onload = image.onerror = null;
  }
  const canvas = document.createElement("canvas");
  canvas.width = innerWidth;
  canvas.height = innerHeight;
  const context = canvas.getContext("2d");
  if (!context) throw new Error("Glass background canvas unavailable");
  context.drawImage(image, 0, 0);
  context.getImageData(0, 0, 1, 1);
  return canvas;
}

export async function captureGlassBackground(
  target: HTMLElement,
  blocked: Set<Element>,
): Promise<HTMLCanvasElement> {
  if (capturing || unfinishedSamples.size)
    throw new Error("Glass background capture still active");
  capturing = true;
  try {
    return await captureBackground(target, blocked);
  } finally {
    capturing = false;
  }
}

import {
  type ComponentType,
  type CSSProperties,
  createContext,
  type Ref,
  type RefObject,
  useContext,
  useLayoutEffect,
} from "react";
import { type GlassIntensity, glassIntensityDefaults } from "@/lib/glass/intensity";
import { acquireGlass, updateGlassConfiguration } from "@/lib/glass/runtime";

export type { GlassIntensity } from "@/lib/glass/intensity";

export type GlassMode = "css" | "auto";

export type GlassOptions = {
  strength?: number;
  blur?: number;
  tint?: string;
  tintOpacity?: number;
  highlight?: number;
};

export type GlassHandle = { refresh: () => void };
export type GlassCaptureTarget =
  | HTMLElement
  | null
  | RefObject<HTMLElement | null>;

export type GlassConfiguration = {
  id: string;
  mode?: GlassMode;
  intensity?: GlassIntensity;
  options?: GlassOptions;
  captureTarget?: GlassCaptureTarget;
};

type GlassContextValue = {
  configuration?: GlassConfiguration;
  intensity?: GlassIntensity;
  enabled: boolean;
  surface: boolean;
};

export const GlassContext = createContext<GlassContextValue>({
  enabled: false,
  surface: false,
});

export type GlassProps = { glass?: boolean; glassIntensity?: GlassIntensity };

export function withGlass<P extends object>(
  Component: ComponentType<P>,
  kind: "surface" | "control" | "scope" | "portal" = "surface",
) {
  function GlassComponent({ glass, glassIntensity, ...props }: P & GlassProps) {
    const context = useContext(GlassContext);
    const enabled =
      glass ?? (context.enabled && (kind !== "surface" || !context.surface));
    const configuration = context.configuration;
    const id = configuration?.id ?? "default";
    const intensity =
      glassIntensity ??
      context.intensity ??
      configuration?.intensity ??
      "default";
    useLayoutEffect(() => {
      if (!enabled) return;
      return acquireGlass({ id });
    }, [enabled, id]);
    useLayoutEffect(() => {
      if (enabled && configuration) updateGlassConfiguration(configuration);
    }, [enabled, configuration]);
    const surface = enabled && kind !== "scope";
    let childSurface = context.surface || surface;
    if (kind === "scope") childSurface = glass !== true && context.surface;
    const options = configuration?.options;
    const originalStyle = (
      props as {
        style?: CSSProperties | ((state: unknown) => CSSProperties | undefined);
      }
    ).style;
    const defaults = glassIntensityDefaults(intensity);
    const materialStyle = {
      "--glass-initial-blur": `${defaults.blur}px`,
      "--glass-initial-opacity": `${defaults.tintOpacity * 100}%`,
    } as CSSProperties & Record<string, unknown>;
    if (options?.tint) materialStyle["--glass-base"] = options.tint;
    if (Number.isFinite(options?.blur))
      materialStyle["--glass-blur"] =
        `${Math.min(24, Math.max(0, options?.blur ?? 0))}px`;
    if (Number.isFinite(options?.tintOpacity))
      materialStyle["--glass-opacity"] =
        `${Math.min(1, Math.max(0, options?.tintOpacity ?? 0)) * 100}%`;
    if (options?.highlight === 0) {
      materialStyle["--glass-edge"] = "none";
      materialStyle["--glass-initial-edge-shadow"] = "0 0 #0000";
    }
    const initialStyle =
      typeof originalStyle === "function"
        ? (state: unknown) => ({ ...originalStyle(state), ...materialStyle })
        : { ...originalStyle, ...materialStyle };
    return (
      <GlassContext.Provider
        value={{
          configuration,
          intensity,
          enabled,
          surface: childSurface,
        }}
      >
        <Component
          {...(props as P)}
          {...(surface
            ? {
                style: initialStyle,
                "data-glass": "true",
                "data-glass-scope": configuration?.id ?? "default",
                "data-glass-intensity": intensity,
                "data-glass-state": "loading",
              }
            : {})}
        />
      </GlassContext.Provider>
    );
  }
  GlassComponent.displayName = `Glass(${Component.displayName ?? Component.name})`;
  return GlassComponent;
}

export type GlassProviderRef = Ref<GlassHandle>;

export function useGlassEnabled(glass?: boolean) {
  const context = useContext(GlassContext);
  return glass ?? (context.enabled && !context.surface);
}

export type GlassTextColor = [number, number, number, number];
export type GlassTextBounds = [number, number, number, number];
export const maxGlassTextColors = 32;

export class GlassContrastError extends Error {
  override name = "GlassContrastError";
}

export function parseGlassColor(color: string): GlassTextColor {
  if (!color || color === "transparent") return [0, 0, 0, 0];
  const canvas = document.createElement("canvas");
  canvas.width = canvas.height = 1;
  const context = canvas.getContext("2d");
  if (!context) return [0.5, 0.5, 0.5, 1];
  context.fillStyle = color;
  context.fillRect(0, 0, 1, 1);
  const bytes = context.getImageData(0, 0, 1, 1).data;
  return [bytes[0] / 255, bytes[1] / 255, bytes[2] / 255, bytes[3] / 255];
}

function luminance(color: readonly number[]) {
  const linear = color
    .slice(0, 3)
    .map((channel) =>
      channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4,
    );
  return linear[0] * 0.2126 + linear[1] * 0.7152 + linear[2] * 0.0722;
}

export function glassTextContrast(
  background: readonly number[],
  text: GlassTextColor,
) {
  const foreground = text
    .slice(0, 3)
    .map(
      (channel, index) => channel * text[3] + background[index] * (1 - text[3]),
    );
  const first = luminance(background) + 0.05;
  const second = luminance(foreground) + 0.05;
  return Math.max(first, second) / Math.min(first, second);
}

export function resolveGlassContrastTint(
  tint: [number, number, number],
  colors: readonly GlassTextColor[],
  minimum: number,
): [number, number, number] | undefined {
  const passes = (candidate: [number, number, number]) =>
    colors.every((color) => glassTextContrast(candidate, color) >= minimum);
  if (passes(tint)) return tint;
  let result: [number, number, number] | undefined;
  let distance = Number.POSITIVE_INFINITY;
  const consider = (candidate: [number, number, number]) => {
    const delta = candidate.reduce(
      (total, channel, index) => total + (channel - tint[index]) ** 2,
      0,
    );
    if (delta < distance && passes(candidate)) {
      result = candidate;
      distance = delta;
    }
  };
  for (let step = 0; step <= 255; step++) {
    const value = step / 255;
    consider([value, value, value]);
    for (const endpoint of [0, 1])
      consider(
        tint.map(
          (channel) =>
            Math.round((channel * (1 - value) + endpoint * value) * 255) / 255,
        ) as [number, number, number],
      );
  }
  return result;
}

export class GlassTextContrastCache {
  private revision = 0;
  private readonly entries = new WeakMap<
    HTMLElement,
    {
      revision: number;
      colors: GlassTextColor[];
      regions: Element[][];
      controls: {
        element: HTMLInputElement | HTMLTextAreaElement;
        filled: boolean;
        placeholder: string;
      }[];
    }
  >();

  invalidate() {
    this.revision++;
  }

  read(surface: HTMLElement): GlassTextColor[] {
    const cached = this.entries.get(surface);
    if (
      cached?.revision === this.revision &&
      cached.controls.every(
        ({ element, filled, placeholder }) =>
          Boolean(element.value) === filled &&
          element.placeholder === placeholder,
      )
    )
      return cached.colors;
    const colors = new Map<string, GlassTextColor>();
    const regions = new Map<string, Element[]>();
    const controls: {
      element: HTMLInputElement | HTMLTextAreaElement;
      filled: boolean;
      placeholder: string;
    }[] = [];
    const add = (element: Element, color: string, opacity = 1) => {
      const parsed = parseGlassColor(color);
      parsed[3] *= opacity;
      if (parsed[3] <= 0) return;
      const key = parsed.join(",");
      colors.set(key, parsed);
      const elements = regions.get(key) ?? [];
      elements.push(element);
      regions.set(key, elements);
    };
    const visit = (element: Element, opacity: number) => {
      if (element !== surface && element.getAttribute("data-glass") === "true")
        return;
      const style = getComputedStyle(element);
      const alpha = Number.parseFloat(style.opacity);
      const effectiveOpacity = opacity * (Number.isFinite(alpha) ? alpha : 1);
      if (
        effectiveOpacity <= 0 ||
        style.display === "none" ||
        style.visibility === "hidden" ||
        style.visibility === "collapse" ||
        element.hasAttribute("hidden") ||
        element.getAttribute("aria-hidden") === "true" ||
        ["SCRIPT", "STYLE", "TEMPLATE", "SVG", "IFRAME"].includes(
          element.tagName.toUpperCase(),
        )
      )
        return;
      if (
        element !== surface &&
        ((style.backgroundImage && style.backgroundImage !== "none") ||
          parseGlassColor(style.backgroundColor)[3] > 0)
      )
        return;
      const input = element as HTMLInputElement | HTMLTextAreaElement;
      if (element.tagName === "INPUT" || element.tagName === "TEXTAREA") {
        if (element.tagName === "INPUT" && input.type === "hidden") return;
        controls.push({
          element: input,
          filled: Boolean(input.value),
          placeholder: input.placeholder,
        });
        if (input.value) add(element, style.color, effectiveOpacity);
        else if (input.placeholder) {
          const placeholder = getComputedStyle(element, "::placeholder");
          const placeholderOpacity = Number.parseFloat(placeholder.opacity);
          add(
            element,
            placeholder.color || style.color,
            effectiveOpacity *
              (Number.isFinite(placeholderOpacity) ? placeholderOpacity : 1),
          );
        }
        return;
      }
      if (
        [...element.childNodes].some(
          (node) => node.nodeType === 3 && Boolean(node.textContent?.trim()),
        )
      )
        add(element, style.color, effectiveOpacity);
      for (const child of element.children) visit(child, effectiveOpacity);
    };
    visit(surface, 1);
    if (!colors.size) add(surface, getComputedStyle(surface).color);
    const result = [...colors.values()];
    this.entries.set(surface, {
      revision: this.revision,
      colors: result,
      regions: [...colors.keys()].map((key) => regions.get(key) ?? [surface]),
      controls,
    });
    return result;
  }

  readBounds(surface: HTMLElement): GlassTextBounds[] {
    this.read(surface);
    const rect = surface.getBoundingClientRect();
    return (this.entries.get(surface)?.regions ?? []).map((elements) => {
      const rectangles = elements
        .map((element) => element.getBoundingClientRect())
        .filter((region) => region.width > 0 && region.height > 0);
      if (!rectangles.length) return [0, 0, rect.width, rect.height];
      return [
        Math.min(...rectangles.map((region) => region.left)) - rect.left,
        Math.min(...rectangles.map((region) => region.top)) - rect.top,
        Math.max(...rectangles.map((region) => region.right)) - rect.left,
        Math.max(...rectangles.map((region) => region.bottom)) - rect.top,
      ];
    });
  }
}

export function glassRadii(
  width: number,
  height: number,
  radii: [string, string, string, string],
) {
  const corners = radii.map((value) => {
    const [horizontal = "0", vertical = horizontal] = value.split(/\s+/);
    const resolve = (length: string, size: number) =>
      Math.max(
        0,
        (Number.parseFloat(length) || 0) *
          (length.endsWith("%") ? size / 100 : 1),
      );
    return { x: resolve(horizontal, width), y: resolve(vertical, height) };
  });
  const [tl, tr, br, bl] = corners;
  const scale = Math.min(
    1,
    width / (tl.x + tr.x),
    width / (bl.x + br.x),
    height / (tl.y + bl.y),
    height / (tr.y + br.y),
  );
  return corners.map((radius) => ({
    x: radius.x * scale,
    y: radius.y * scale,
  }));
}

export function glassEdge(
  width: number,
  height: number,
  radii: [string, string, string, string],
  highlight: number,
  color: readonly number[] = [1, 1, 1],
) {
  if (highlight <= 0 || width <= 0 || height <= 0) return "none";
  const corners = glassRadii(width, height, radii);
  const outline = (inset: number) => {
    const [tl, tr, br, bl] = corners.map((radius) => ({
      x: Math.max(0, radius.x - inset),
      y: Math.max(0, radius.y - inset),
    }));
    const right = width - inset;
    const bottom = height - inset;
    return `M${inset + tl.x} ${inset}H${right - tr.x}A${tr.x} ${tr.y} 0 0 1 ${right} ${inset + tr.y}V${bottom - br.y}A${br.x} ${br.y} 0 0 1 ${right - br.x} ${bottom}H${inset + bl.x}A${bl.x} ${bl.y} 0 0 1 ${inset} ${bottom - bl.y}V${inset + tl.y}A${tl.x} ${tl.y} 0 0 1 ${inset + tl.x} ${inset}Z`;
  };
  const opacity = Math.min(1, highlight * 2);
  const stroke = `rgb(${color
    .slice(0, 3)
    .map((channel) => Math.round((0.8 + channel * 0.2) * 255))
    .join(" ")})`;
  const [topLeft, , bottomRight] = corners;
  const arc = 1 - Math.SQRT1_2;
  const reach = Math.max(12, Math.min(width, height) * 0.7);
  const reachX = Math.max(reach, width * 0.65);
  const reachY = Math.max(reach, height * 0.65);
  const lights = [
    { x: topLeft.x * arc, y: topLeft.y * arc },
    { x: width - bottomRight.x * arc, y: height - bottomRight.y * arc },
  ];
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
    <defs>
      ${lights
        .map(
          (
            light,
            index,
          ) => `<radialGradient id="light${index}" gradientUnits="userSpaceOnUse" cx="0" cy="0" r="1" gradientTransform="translate(${light.x} ${light.y}) scale(${reachX} ${reachY})">
        <stop stop-color="${stroke}" stop-opacity=".85"/>
        <stop offset=".5" stop-color="${stroke}" stop-opacity=".36"/>
        <stop offset=".85" stop-color="${stroke}" stop-opacity=".06"/>
        <stop offset="1" stop-color="${stroke}" stop-opacity="0"/>
      </radialGradient>`,
        )
        .join("")}
      <filter id="soft" x="-5%" y="-5%" width="110%" height="110%" color-interpolation-filters="sRGB">
        <feGaussianBlur stdDeviation=".55"/>
      </filter>
    </defs>
    ${lights
      .map(
        (_, index) =>
          `<path d="${outline(0.65)}" fill="none" stroke="url(#light${index})" stroke-width=".9" opacity="${opacity}" filter="url(#soft)"/>`,
      )
      .join("")}
  </svg>`;
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}")`;
}

export function glassShadow(highlight: number) {
  if (highlight <= 0) return "0 0 #0000";
  const opacity = Number(Math.min(highlight / 3, 0.28).toFixed(3));
  return `1px -1px 2px -0.5px rgb(0 0 0 / ${opacity}), -1px 1px 2px -0.5px rgb(0 0 0 / ${opacity})`;
}

export type GlassIntensity = "sm" | "default" | "lg";

const intensityDefaults = {
  sm: { blur: 4, tintOpacity: 0.4 },
  default: { blur: 6, tintOpacity: 0.6 },
  lg: { blur: 8, tintOpacity: 0.78 },
} as const;

export function glassIntensityDefaults(intensity?: string) {
  if (intensity === "sm") return intensityDefaults.sm;
  if (intensity === "lg") return intensityDefaults.lg;
  return intensityDefaults.default;
}

import type {} from "@/lib/sui/types/webgpu";

/// <reference types="@webgpu/types" />

import {
  type Effect,
  effect,
  type Gpu,
  frame as gpuFrame,
  init,
  sampler,
  type Texture,
  target,
  texture,
} from "vgpu";

import {
  GlassContrastError,
  type GlassTextBounds,
  type GlassTextColor,
  maxGlassTextColors,
  resolveGlassContrastTint,
} from "@/lib/glass/contrast";

export type GlassFrame = {
  width: number;
  height: number;
  margin: number;
  origin?: [number, number];
  radius: [number, number, number, number];
  radiusY?: [number, number, number, number];
  strength: number;
  blur: number;
  tint: [number, number, number];
  tintOpacity: number;
  foreground: [number, number, number];
  textColors?: readonly GlassTextColor[];
  textBounds?: readonly GlassTextBounds[];
  minimumContrast?: number;
};

const shader = `
struct Params {
  surface: vec4f,
  source: vec4f,
  radii: vec4f,
  verticalRadii: vec4f,
  material: vec2f,
  tint: vec3f,
  minimumContrast: f32,
  contrastMaterial: vec4f,
  textColors: array<vec4f, ${maxGlassTextColors}>,
  textBounds: array<vec4f, ${maxGlassTextColors}>,
};
@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var background: texture_2d<f32>;
@group(0) @binding(2) var linearSampler: sampler;

@vertex fn vertexMain(@builtin(vertex_index) index: u32) -> @builtin(position) vec4f {
  var positions = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
  return vec4f(positions[index], 0.0, 1.0);
}
fn luminance(rgb: vec3f) -> f32 {
  let linear = select(rgb / vec3f(12.92), pow((rgb + vec3f(0.055)) / vec3f(1.055), vec3f(2.4)), rgb > vec3f(0.04045));
  return dot(linear, vec3f(0.2126, 0.7152, 0.0722));
}
fn contrast(a: vec3f, b: vec3f) -> f32 {
  let x = luminance(a) + 0.05;
  let y = luminance(b) + 0.05;
  return max(x, y) / min(x, y);
}
fn supportsTextContrast(background: vec3f, point: vec2f) -> bool {
  for (var index = 0u; index < u32(params.contrastMaterial.w); index++) {
    let bounds = params.textBounds[index];
    if (point.x < bounds.x || point.y < bounds.y || point.x > bounds.z || point.y > bounds.w) { continue; }
    let text = params.textColors[index];
    let foreground = mix(background, text.xyz, text.w);
    if (contrast(background, foreground) < params.minimumContrast) { return false; }
  }
  return true;
}
fn ellipseDistance(x: f32, y: f32, rx: f32, ry: f32) -> f32 {
  let k0 = sqrt(x * x / (rx * rx) + y * y / (ry * ry));
  let k1 = sqrt(x * x / (rx * rx * rx * rx) + y * y / (ry * ry * ry * ry));
  if (k1 == 0.0) { return -min(rx, ry); }
  return k0 * (k0 - 1.0) / k1;
}
fn roundedDistance(p: vec2f) -> f32 {
  let width = params.surface.x;
  let height = params.surface.y;
  var distance = max(max(-p.x, p.x - width), max(-p.y, p.y - height));
  if (params.radii.x > 0.0 && params.verticalRadii.x > 0.0 && p.x < params.radii.x && p.y < params.verticalRadii.x) {
    distance = max(distance, ellipseDistance(p.x - params.radii.x, p.y - params.verticalRadii.x, params.radii.x, params.verticalRadii.x));
  }
  if (params.radii.y > 0.0 && params.verticalRadii.y > 0.0 && p.x > width - params.radii.y && p.y < params.verticalRadii.y) {
    distance = max(distance, ellipseDistance(p.x - (width - params.radii.y), p.y - params.verticalRadii.y, params.radii.y, params.verticalRadii.y));
  }
  if (params.radii.z > 0.0 && params.verticalRadii.z > 0.0 && p.x > width - params.radii.z && p.y > height - params.verticalRadii.z) {
    distance = max(distance, ellipseDistance(p.x - (width - params.radii.z), p.y - (height - params.verticalRadii.z), params.radii.z, params.verticalRadii.z));
  }
  if (params.radii.w > 0.0 && params.verticalRadii.w > 0.0 && p.x < params.radii.w && p.y > height - params.verticalRadii.w) {
    distance = max(distance, ellipseDistance(p.x - params.radii.w, p.y - (height - params.verticalRadii.w), params.radii.w, params.verticalRadii.w));
  }
  return distance;
}
fn sourceColor(p: vec2f) -> vec3f {
  let uv = clamp((p + params.source.zw) / params.source.xy, vec2f(0.0), vec2f(1.0));
  return textureSampleLevel(background, linearSampler, uv, 0.0).rgb;
}
@fragment fn fragmentMain(@builtin(position) pixel: vec4f) -> @location(0) vec4f {
  let p = pixel.xy * params.surface.xy / params.surface.zw;
  let distance = roundedDistance(p);
  let gradient = vec2f(
    roundedDistance(p + vec2f(0.4, 0.0)) - roundedDistance(p - vec2f(0.4, 0.0)),
    roundedDistance(p + vec2f(0.0, 0.4)) - roundedDistance(p - vec2f(0.0, 0.4))
  ) + vec2f(0.00001);
  let normal = gradient / max(length(gradient), 0.00001);
  let depth = max(-distance, 0.0);
  let bevel = pow(clamp(1.0 - depth / 17.0, 0.0, 1.0), 2.0);
  let displaced = p - normal * bevel * params.material.y * 0.45;
  let split = normal * bevel * min(params.material.y * 0.014, 0.45);
  let sampled = vec3f(sourceColor(displaced + split).r, sourceColor(displaced).g, sourceColor(displaced - split).b);
  let luminanceValue = dot(sampled, vec3f(0.2126, 0.7152, 0.0722));
  let saturated = mix(vec3f(luminanceValue), sampled, 1.12);
  var result = mix(saturated, params.tint, params.material.x);
  result = clamp(result, vec3f(0.0), vec3f(1.0));
  if (params.minimumContrast > 0.0 && !supportsTextContrast(result, p)) {
    let safeTint = params.contrastMaterial.xyz;
    for (var index = 0; index < 8; index++) {
      if (supportsTextContrast(result, p)) { break; }
      result = mix(result, safeTint, 0.18);
    }
    if (!supportsTextContrast(result, p)) { result = safeTint; }
  }
  return vec4f(result, 1.0 - smoothstep(-0.65, 0.65, distance));
}`;

const gaussianShader = `
struct BlurParams {
  size: vec2f,
  step: vec2f,
  sigma: f32,
  radius: f32,
  padding: vec2f,
};
@group(0) @binding(0) var<uniform> params: BlurParams;
@group(0) @binding(1) var background: texture_2d<f32>;
@group(0) @binding(2) var linearSampler: sampler;
@vertex fn vertexMain(@builtin(vertex_index) index: u32) -> @builtin(position) vec4f {
  var positions = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
  return vec4f(positions[index], 0.0, 1.0);
}
@fragment fn fragmentMain(@builtin(position) pixel: vec4f) -> @location(0) vec4f {
  let uv = pixel.xy / params.size;
  var result = textureSampleLevel(background, linearSampler, uv, 0.0);
  var weight = 1.0;
  for (var offset = 1.0; offset <= params.radius; offset += 2.0) {
    let first = exp(-0.5 * pow(offset / params.sigma, 2.0));
    let second = select(0.0, exp(-0.5 * pow((offset + 1.0) / params.sigma, 2.0)), offset + 1.0 <= params.radius);
    let pairWeight = first + second;
    let delta = params.step * (offset + second / pairWeight);
    result += (textureSampleLevel(background, linearSampler, uv + delta, 0.0) + textureSampleLevel(background, linearSampler, uv - delta, 0.0)) * pairWeight;
    weight += 2.0 * pairWeight;
  }
  return result / weight;
}`;

type Background = {
  texture: Texture;
  width: number;
  height: number;
  filtered: Map<number, Texture>;
};

export class GlassRenderer {
  private readonly refraction: Effect;
  private readonly gaussian: [Effect, Effect];
  private readonly linearSampler: ReturnType<typeof sampler>;
  private readonly resources = new Set<Texture>();
  private readonly backgrounds = new Map<HTMLCanvasElement, Background>();
  private readonly contrastTints = new Map<string, [number, number, number]>();
  private queue: Promise<void> = Promise.resolve();
  private disposed = false;
  private failure?: Error;
  private readonly abort = () => this.destroy();
  private readonly unsubscribeError: () => void;

  private constructor(
    private readonly gpu: Gpu,
    private readonly signal?: AbortSignal,
  ) {
    this.unsubscribeError = gpu.onError((error) => {
      this.failure = new Error(error.message);
    });
    this.linearSampler = sampler(gpu, {
      minFilter: "linear",
      magFilter: "linear",
      addressModeU: "clamp-to-edge",
      addressModeV: "clamp-to-edge",
    });
    this.refraction = effect(gpu, shader, { label: "Glass refraction" });
    this.gaussian = [
      effect(gpu, gaussianShader, { label: "Glass horizontal blur" }),
      effect(gpu, gaussianShader, { label: "Glass vertical blur" }),
    ];
    signal?.addEventListener("abort", this.abort, { once: true });
    void gpu.gpu.lost.then((info) => {
      if (!this.disposed)
        this.failure = new Error(info.message || "Glass GPU device lost");
    });
  }

  static async create(signal?: AbortSignal): Promise<GlassRenderer> {
    if (signal?.aborted)
      throw new DOMException("Glass initialization cancelled", "AbortError");
    if (typeof navigator === "undefined" || !navigator.gpu)
      throw new Error("WebGPU unavailable");
    const gpu = await init({ powerPreference: "low-power", label: "Glass" });
    if (signal?.aborted) {
      gpu.dispose();
      throw new DOMException("Glass initialization cancelled", "AbortError");
    }
    let renderer: GlassRenderer | undefined;
    try {
      renderer = new GlassRenderer(gpu, signal);
      await Promise.all([
        renderer.refraction.compile({ colors: ["rgba8unorm"] }),
        renderer.gaussian[0].compile({ colors: ["rgba8unorm"] }),
        renderer.gaussian[1].compile({ colors: ["rgba8unorm"] }),
      ]);
      renderer.assertActive();
      return renderer;
    } catch (error) {
      if (renderer) renderer.destroy();
      else gpu.dispose();
      throw error;
    }
  }

  private assertActive() {
    if (this.disposed) throw new Error("Glass renderer disposed");
    if (this.failure) throw this.failure;
  }

  private releaseTexture(image: Texture) {
    if (this.resources.delete(image)) image.destroy();
  }

  private releaseBackground(source: HTMLCanvasElement) {
    const background = this.backgrounds.get(source);
    if (!background) return;
    this.backgrounds.delete(source);
    this.releaseTexture(background.texture);
    for (const image of background.filtered.values())
      this.releaseTexture(image);
  }

  private background(source: HTMLCanvasElement): Texture {
    const cached = this.backgrounds.get(source);
    if (
      cached &&
      cached.width === source.width &&
      cached.height === source.height
    ) {
      this.backgrounds.delete(source);
      this.backgrounds.set(source, cached);
      return cached.texture;
    }
    this.releaseBackground(source);
    const image = texture(this.gpu, {
      kind: "2d",
      label: "Glass background",
      size: [source.width, source.height],
      format: "rgba8unorm",
      usage: ["texture_binding", "copy_dst", "render_attachment"],
    });
    this.resources.add(image);
    try {
      this.gpu.gpu.queue.copyExternalImageToTexture(
        { source, flipY: false },
        { texture: image.gpu, premultipliedAlpha: false },
        [source.width, source.height],
      );
      this.backgrounds.set(source, {
        texture: image,
        width: source.width,
        height: source.height,
        filtered: new Map(),
      });
      if (this.backgrounds.size > 4) {
        const oldest = this.backgrounds.keys().next().value;
        if (oldest) this.releaseBackground(oldest);
      }
      return image;
    } catch (error) {
      this.releaseTexture(image);
      throw error;
    }
  }

  private filteredBackground(
    source: HTMLCanvasElement,
    blur: number,
    temporary: Texture[],
  ): Texture {
    const image = this.background(source);
    if (blur <= 0) return image;
    const background = this.backgrounds.get(source);
    if (!background) throw new Error("Glass background unavailable");
    const cached = background.filtered.get(blur);
    if (cached) {
      background.filtered.delete(blur);
      background.filtered.set(blur, cached);
      return cached;
    }
    // Share the original upload and each blur level across surfaces. Above 2 CSS
    // pixels, half-resolution Gaussian targets bound memory and sampling cost.
    const scale = blur >= 2 ? 0.5 : 1;
    const width = Math.max(1, Math.round(source.width * scale));
    const height = Math.max(1, Math.round(source.height * scale));
    const makeTarget = (label: string) => {
      const output = target(this.gpu, {
        label,
        size: [width, height],
        format: "rgba8unorm",
        clearColor: [0, 0, 0, 0],
      });
      this.resources.add(output.color);
      return output;
    };
    const horizontal = makeTarget("Glass Gaussian intermediate");
    temporary.push(horizontal.color);
    const vertical = makeTarget("Glass blurred background");
    background.filtered.set(blur, vertical.color);
    if (background.filtered.size > 3) {
      const oldest = background.filtered.keys().next().value;
      if (oldest !== undefined) {
        const previous = background.filtered.get(oldest);
        if (previous) this.releaseTexture(previous);
        background.filtered.delete(oldest);
      }
    }
    const sigma = blur * scale;
    const radius = Math.ceil(sigma * 3);
    const stages = [
      { input: image, output: horizontal, step: [1 / width, 0] },
      { input: horizontal.color, output: vertical, step: [0, 1 / height] },
    ];
    for (const [index, stage] of stages.entries()) {
      this.gaussian[index].set({
        params: {
          size: [width, height],
          step: stage.step,
          sigma,
          radius,
          padding: [0, 0],
        },
        background: stage.input,
        linearSampler: this.linearSampler,
      });
    }
    gpuFrame(this.gpu, (frame) => {
      frame.pass(horizontal, this.gaussian[0]);
      frame.pass(vertical, this.gaussian[1]);
    });
    return vertical.color;
  }

  render(source: HTMLCanvasElement, frame: GlassFrame): Promise<Blob> {
    const operation = this.queue.then(() => this.renderFrame(source, frame));
    this.queue = operation.then(
      () => {},
      () => {},
    );
    return operation;
  }

  private async renderFrame(
    source: HTMLCanvasElement,
    frame: GlassFrame,
  ): Promise<Blob> {
    this.assertActive();
    const textColors: readonly GlassTextColor[] = frame.textColors ?? [
      [...frame.foreground, 1],
    ];
    if (
      textColors.length > maxGlassTextColors ||
      textColors.some(
        (color) =>
          color.length !== 4 ||
          color.some(
            (channel) =>
              !Number.isFinite(channel) || channel < 0 || channel > 1,
          ),
      )
    )
      throw new GlassContrastError("Unsupported glass text colors");
    const textBounds =
      frame.textBounds ??
      textColors.map(() => [0, 0, frame.width, frame.height]);
    if (
      textBounds.length !== textColors.length ||
      textBounds.some(
        (bounds) => bounds.length !== 4 || !bounds.every(Number.isFinite),
      )
    )
      throw new GlassContrastError("Unsupported glass text bounds");
    const minimum = frame.minimumContrast ?? 4.5;
    const contrastMinimum = minimum > 0 ? minimum + 0.05 : 0;
    const contrastKey = JSON.stringify([
      frame.tint,
      textColors,
      contrastMinimum,
    ]);
    let contrastTint = this.contrastTints.get(contrastKey);
    if (!contrastTint) {
      contrastTint = resolveGlassContrastTint(
        frame.tint,
        textColors,
        contrastMinimum,
      );
      if (!contrastTint)
        throw new GlassContrastError(
          "Glass text colors have no shared contrast background",
        );
      if (this.contrastTints.size >= 64) this.contrastTints.clear();
      this.contrastTints.set(contrastKey, contrastTint);
    }
    if (
      ![
        frame.width,
        frame.height,
        frame.margin,
        frame.strength,
        frame.blur,
        frame.tintOpacity,
        frame.minimumContrast ?? 4.5,
        ...(frame.origin ?? [frame.margin, frame.margin]),
        ...frame.radius,
        ...(frame.radiusY ?? frame.radius),
        ...frame.tint,
        ...frame.foreground,
      ].every(Number.isFinite) ||
      frame.blur < 0 ||
      frame.blur > 24 ||
      frame.width <= 0 ||
      frame.height <= 0 ||
      source.width <= 0 ||
      source.height <= 0
    )
      throw new Error("Invalid glass frame dimensions or material");
    const scale = Math.min(Math.max(window.devicePixelRatio || 1, 1), 1.5);
    const width = Math.max(1, Math.round(frame.width * scale));
    const height = Math.max(1, Math.round(frame.height * scale));
    const bytesPerRow = Math.ceil((width * 4) / 256) * 256;
    if (
      Math.max(width, height, source.width, source.height) >
        this.gpu.gpu.limits.maxTextureDimension2D ||
      bytesPerRow * height > this.gpu.gpu.limits.maxBufferSize
    )
      throw new Error("Glass frame exceeds GPU limits");
    const temporary: Texture[] = [];
    let scopeOpen = true;
    this.gpu.gpu.pushErrorScope("validation");
    try {
      const input = this.filteredBackground(source, frame.blur, temporary);
      const output = target(this.gpu, {
        label: "Glass frame",
        size: [width, height],
        format: "rgba8unorm",
        clearColor: [0, 0, 0, 0],
      });
      this.resources.add(output.color);
      temporary.push(output.color);
      const padding = () =>
        Array.from({ length: maxGlassTextColors }, () => [0, 0, 0, 0]);
      const colors = padding();
      const bounds = padding();
      textColors.forEach((color, index) => {
        colors[index] = [...color];
      });
      textBounds.forEach((region, index) => {
        bounds[index] = [...region];
      });
      this.refraction.set({
        params: {
          surface: [frame.width, frame.height, width, height],
          source: [
            source.width,
            source.height,
            ...(frame.origin ?? [frame.margin, frame.margin]),
          ],
          radii: frame.radius,
          verticalRadii: frame.radiusY ?? frame.radius,
          material: [frame.tintOpacity, frame.strength],
          tint: frame.tint,
          minimumContrast: contrastMinimum,
          contrastMaterial: [...contrastTint, textColors.length],
          textColors: colors,
          textBounds: bounds,
        },
        background: input,
        linearSampler: this.linearSampler,
      });
      gpuFrame(this.gpu, (frame) => frame.pass(output, this.refraction));
      await this.gpu.settled();
      const validation = await this.gpu.gpu.popErrorScope();
      scopeOpen = false;
      if (validation) throw new Error(validation.message);
      this.assertActive();
      const bytes = await output.color.read({ mipLevel: 0, region: "all" });
      this.assertActive();
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const context = canvas.getContext("2d");
      if (!context) throw new Error("Unable to export glass pixels");
      const image = context.createImageData(width, height);
      image.data.set(bytes);
      context.putImageData(image, 0, 0);
      const blob = await new Promise<Blob>((resolve, reject) =>
        canvas.toBlob((result) => {
          if (result) resolve(result);
          else reject(new Error("Unable to export glass frame"));
        }, "image/png"),
      );
      canvas.width = canvas.height = 1;
      this.assertActive();
      return blob;
    } catch (error) {
      this.releaseBackground(source);
      throw error;
    } finally {
      if (scopeOpen) await this.gpu.gpu.popErrorScope().catch(() => {});
      for (const image of temporary) this.releaseTexture(image);
    }
  }

  destroy() {
    if (this.disposed) return;
    this.disposed = true;
    this.signal?.removeEventListener("abort", this.abort);
    this.unsubscribeError();
    for (const resource of this.resources) resource.destroy();
    this.resources.clear();
    this.backgrounds.clear();
    this.contrastTints.clear();
    this.gpu.dispose();
  }
}

import {
  acquireGlassCaptureFonts,
  captureGlassBackground,
  glassLayoutSize,
} from "@/lib/glass/capture";
import type { GlassConfiguration, GlassOptions } from "@/lib/glass/context";
import {
  GlassContrastError,
  GlassTextContrastCache,
  parseGlassColor as parseColor,
} from "@/lib/glass/contrast";
import { glassEdge, glassRadii, glassShadow } from "@/lib/glass/edge";
import { glassIntensityDefaults } from "@/lib/glass/intensity";
import type { GlassRenderer } from "@/lib/glass/renderer";

const managers = new Map<string, GlassManager>();
let renderer: GlassRenderer | undefined;
let initialization: AbortController | undefined;
let queue = Promise.resolve();
let nextSurface = 0;
const elementIds = new WeakMap<Element, number>();
const backgroundVersions = new WeakMap<HTMLElement, number>();
let sceneRevision = 0;
let lastSnapshotTime = 0;
let sharedSnapshots = new WeakMap<
  HTMLElement,
  { revision: number; frames: Map<string, HTMLCanvasElement> }
>();

function idFor(element: Element) {
  let id = elementIds.get(element);
  if (id === undefined) {
    id = ++nextSurface;
    elementIds.set(element, id);
  }
  return id;
}

function invalidateScene() {
  sceneRevision++;
}

function backgroundChanged(element: HTMLElement) {
  backgroundVersions.set(element, (backgroundVersions.get(element) ?? 0) + 1);
  for (const manager of managers.values()) manager.refreshDependency(element);
}

function overlaps(a: DOMRect, b: DOMRect) {
  return (
    a.right > b.left && a.left < b.right && a.bottom > b.top && a.top < b.bottom
  );
}

const clamp = (
  value: number | undefined,
  fallback: number,
  low: number,
  high: number,
) =>
  Math.min(
    high,
    Math.max(low, Number.isFinite(value) ? (value as number) : fallback),
  );

function visible(element: Element) {
  const bounds = element.getBoundingClientRect();
  const style = getComputedStyle(element);
  return (
    element.isConnected &&
    bounds.width > 0 &&
    bounds.height > 0 &&
    bounds.right > 0 &&
    bounds.bottom > 0 &&
    bounds.left < innerWidth &&
    bounds.top < innerHeight &&
    style.visibility !== "hidden" &&
    style.display !== "none" &&
    !element.closest("[hidden],[inert],[data-closed]")
  );
}

function surfaceRadii(
  element: HTMLElement,
  rect: DOMRect,
  style: CSSStyleDeclaration,
): [string, string, string, string] {
  const size = glassLayoutSize(element, rect);
  const corners = glassRadii(size.width, size.height, [
    style.borderTopLeftRadius,
    style.borderTopRightRadius,
    style.borderBottomRightRadius,
    style.borderBottomLeftRadius,
  ]);
  return corners.map(
    ({ x, y }) =>
      `${(x * rect.width) / size.width}px ${(y * rect.height) / size.height}px`,
  ) as [string, string, string, string];
}

function stackingLayer(element: Element) {
  const style = getComputedStyle(element);
  const positioned = Boolean(style.position && style.position !== "static");
  const parentDisplay = element.parentElement
    ? getComputedStyle(element.parentElement).display
    : "";
  const ordered =
    positioned || /^(?:inline-)?(?:flex|grid)$/.test(parentDisplay);
  const z = ordered ? Number.parseInt(style.zIndex, 10) : Number.NaN;
  const effect = (value: string) => Boolean(value && value !== "none");
  const context =
    element === document.documentElement ||
    (ordered && Number.isFinite(z)) ||
    style.position === "fixed" ||
    style.position === "sticky" ||
    Number.parseFloat(style.opacity) < 1 ||
    effect(style.transform) ||
    effect(style.translate) ||
    effect(style.scale) ||
    effect(style.rotate) ||
    effect(style.filter) ||
    effect(style.backdropFilter) ||
    effect(style.getPropertyValue("-webkit-backdrop-filter")) ||
    effect(style.perspective) ||
    effect(style.clipPath) ||
    effect(style.maskImage) ||
    effect(style.getPropertyValue("mask-border-source")) ||
    style.isolation === "isolate" ||
    /^(?:size|inline-size)$/.test(style.containerType) ||
    Boolean(style.mixBlendMode && style.mixBlendMode !== "normal") ||
    /\b(?:layout|paint|strict|content)\b/.test(style.contain) ||
    /\b(?:transform|translate|scale|rotate|opacity|filter|backdrop-filter|perspective|clip-path|mask|isolation)\b/.test(
      style.willChange,
    );
  let phase: number | undefined;
  if (context || positioned) {
    phase = 0;
    if (Number.isFinite(z)) phase = z;
  }
  return { element, context, phase };
}

function layerOrder(a: Element, b: Element): number | undefined {
  if (
    document.fullscreenElement ||
    a.closest("dialog[open],[popover]") ||
    b.closest("dialog[open],[popover]")
  )
    return;
  const chain = (element: Element) => {
    const layers: ReturnType<typeof stackingLayer>[] = [];
    for (let node: Element | null = element; node; node = node.parentElement) {
      const style = getComputedStyle(node);
      if (
        style.transformStyle === "preserve-3d" ||
        (style.perspective && style.perspective !== "none") ||
        (style.animationName &&
          style.animationName !== "none" &&
          /\b(?:forwards|both)\b/.test(style.animationFillMode))
      )
        return;
      const layer = stackingLayer(node);
      if (layer.context) layers.unshift(layer);
    }
    return layers;
  };
  const left = chain(a);
  const right = chain(b);
  if (!left || !right) return;
  let index = 0;
  while (left[index]?.element === right[index]?.element && left[index]) index++;
  const paintUnit = (element: Element, context?: Element) => {
    for (
      let node: Element | null = element;
      node && node !== context;
      node = node.parentElement
    ) {
      const layer = stackingLayer(node);
      if (layer.phase !== undefined) return layer;
    }
    return stackingLayer(element);
  };
  const common = left[index - 1]?.element;
  const x = left[index] ?? paintUnit(a, common);
  const y = right[index] ?? paintUnit(b, common);
  if (x.phase === undefined && y.phase === undefined) return;
  if (x.phase === undefined)
    return y.phase !== undefined && y.phase < 0 ? 1 : -1;
  if (y.phase === undefined) return x.phase < 0 ? -1 : 1;
  if (x.phase !== y.phase) return x.phase > y.phase ? 1 : -1;
  // Flex/grid paint order can differ from DOM order; leave that case to the CSS fallback.
  for (const element of [x.element, y.element]) {
    for (let node: Element | null = element; node; node = node.parentElement)
      if (Number.parseInt(getComputedStyle(node).order, 10)) return;
  }
  const order = x.element.compareDocumentPosition(y.element);
  if (order & 1) return;
  if (order & 4) return -1;
  if (order & 2) return 1;
}

function higherLayers(surface: HTMLElement) {
  const blocked = new Set<Element>([surface]);
  if (surface.dataset.slot === "tabs-indicator") {
    for (const tab of surface.parentElement?.querySelectorAll('[role="tab"]') ??
      [])
      blocked.add(tab);
  }
  const rect = surface.getBoundingClientRect();
  for (const fx of [0.1, 0.5, 0.9]) {
    for (const fy of [0.1, 0.5, 0.9]) {
      const x = Math.max(
        0,
        Math.min(innerWidth - 1, rect.left + rect.width * fx),
      );
      const y = Math.max(
        0,
        Math.min(innerHeight - 1, rect.top + rect.height * fy),
      );
      const stack = document.elementsFromPoint(x, y);
      const index = stack.findIndex(
        (element) => element === surface || surface.contains(element),
      );
      if (index < 0) continue;
      for (const element of stack.slice(0, index)) {
        if (!element.contains(surface) && !surface.contains(element))
          blocked.add(element);
      }
    }
  }
  for (const candidate of document.body.querySelectorAll("*")) {
    if (
      candidate.contains(surface) ||
      surface.contains(candidate) ||
      [...blocked].some((item) => item.contains(candidate)) ||
      candidate.closest("[data-glass-exclude],[data-glass-decoration]") ||
      !visible(candidate)
    )
      continue;
    const bounds = candidate.getBoundingClientRect();
    if (!overlaps(bounds, rect)) continue;
    const x = Math.max(
      0,
      Math.min(
        innerWidth - 1,
        (Math.max(bounds.left, rect.left) +
          Math.min(bounds.right, rect.right)) /
          2,
      ),
    );
    const y = Math.max(
      0,
      Math.min(
        innerHeight - 1,
        (Math.max(bounds.top, rect.top) +
          Math.min(bounds.bottom, rect.bottom)) /
          2,
      ),
    );
    const stack = document.elementsFromPoint(x, y);
    const surfaceIndex = stack.findIndex(
      (element) => element === surface || surface.contains(element),
    );
    const candidateIndex = stack.findIndex(
      (element) => element === candidate || candidate.contains(element),
    );
    if (candidateIndex >= 0 && surfaceIndex >= 0) {
      if (candidateIndex < surfaceIndex) blocked.add(candidate);
      continue;
    }
    if (
      getComputedStyle(candidate).pointerEvents !== "none" &&
      candidateIndex < 0
    )
      continue;
    const order = layerOrder(candidate, surface);
    if (order === undefined)
      throw new Error("Glass background has an ambiguous overlapping layer");
    if (order > 0) blocked.add(candidate);
  }
  return blocked;
}

function styleWithoutFrame(style: string | null) {
  return (style ?? "")
    .replace(
      /--glass-(?:frame|edge|initial-edge-shadow|base|blur|opacity|tint-opacity):[^;]+;?/g,
      "",
    )
    .trim();
}

function geometryMutation(record: MutationRecord) {
  if (
    record.type === "attributes" &&
    record.attributeName === "data-glass-motion" &&
    record.target instanceof HTMLElement &&
    record.target.dataset.glass === "true"
  )
    return true;
  if (
    record.type !== "attributes" ||
    record.attributeName !== "style" ||
    !(record.target instanceof HTMLElement) ||
    record.target.dataset.glass !== "true"
  )
    return false;
  const position = getComputedStyle(record.target).position;
  if (position !== "absolute" && position !== "fixed") return false;
  const withoutGeometry = (style: string | null) =>
    styleWithoutFrame(style)
      .split(";")
      .map((declaration) => declaration.trim())
      .filter(
        (declaration) =>
          declaration &&
          !/^(?:translate|transform|width|height|top|left|right|bottom|visibility)\s*:/.test(
            declaration,
          ),
      )
      .join(";");
  return (
    withoutGeometry(record.oldValue) ===
    withoutGeometry(record.target.getAttribute("style"))
  );
}

function relevantMutation(record: MutationRecord) {
  if (
    record.target instanceof Element &&
    record.target.closest("[data-glass-decoration]")
  )
    return false;
  if (
    record.target instanceof Element &&
    record.target.getAttribute("data-glass") !== "true" &&
    record.target.closest('[data-glass="true"][data-glass-frozen="true"]')
  )
    return false;
  if (
    record.type === "childList" &&
    [...record.addedNodes, ...record.removedNodes].every(
      (node) =>
        node instanceof Element && node.hasAttribute("data-glass-decoration"),
    )
  )
    return false;
  if (record.type === "attributes") {
    if (
      record.attributeName === "data-glass-state" ||
      record.attributeName === "data-glass-capture-id"
    )
      return false;
    if (
      record.attributeName === "style" &&
      record.target instanceof HTMLElement &&
      record.target.dataset.glass === "true"
    ) {
      return (
        styleWithoutFrame(record.oldValue) !==
        styleWithoutFrame(record.target.getAttribute("style"))
      );
    }
    return true;
  }
  return true;
}

function nativeBackground(element: HTMLElement) {
  const probe = element.cloneNode(false) as HTMLElement;
  probe.removeAttribute("data-glass-state");
  probe.removeAttribute("id");
  probe.setAttribute("data-glass-decoration", "");
  probe.setAttribute("aria-hidden", "true");
  probe.style.position = "fixed";
  probe.style.visibility = "hidden";
  probe.style.pointerEvents = "none";
  try {
    element.parentElement?.append(probe);
    const style = getComputedStyle(probe);
    const background = style.backgroundColor;
    return parseColor(background)[3] > 0
      ? background
      : style.getPropertyValue("--popover").trim() || "#fff";
  } finally {
    probe.remove();
  }
}

type SurfaceState = {
  url?: string;
  base: string;
  tint: [number, number, number];
  opacity: number;
  materialKey?: string;
  frameMaterial?: string;
  frameKey?: string;
  edgeKey?: string;
  edgeDirty?: boolean;
};

class GlassManager {
  leases = 0;
  private surfaces = new Map<HTMLElement, SurfaceState>();
  private observer: MutationObserver;
  private resizeObserver: ResizeObserver;
  private intersectionObserver: IntersectionObserver;
  private timer: ReturnType<typeof setTimeout> | undefined;
  private queued = false;
  private disposed = false;
  private dirty = false;
  private materialsDirty = true;
  private scrollingDirty = false;
  private lastCapture = 0;
  private motionFrame = 0;
  private moving = new Map<HTMLElement, number>();
  private pendingFrames = new Map<string, HTMLImageElement>();
  private captureFonts = new Map<Document, () => void>();
  private options: GlassOptions;
  private configurationVersion = 0;
  private readonly textContrast = new GlassTextContrastCache();
  private removeListeners: () => void;

  constructor(private configuration: GlassConfiguration) {
    this.configuration = {
      ...configuration,
      mode: configuration.mode ?? "auto",
    };
    this.options = configuration.options ?? {};
    this.resizeObserver = new ResizeObserver((entries) => {
      let layoutChanged = false;
      for (const { target } of entries) {
        if (!(target instanceof HTMLElement)) continue;
        const state = this.surfaces.get(target);
        if (state) state.edgeDirty = true;
        const position = getComputedStyle(target).position;
        if (position !== "absolute" && position !== "fixed")
          layoutChanged = true;
      }
      if (layoutChanged) {
        this.materialsDirty = true;
        this.textContrast.invalidate();
        invalidateScene();
      }
      this.schedule(false, !layoutChanged);
    });
    this.intersectionObserver = new IntersectionObserver(() => this.schedule());
    this.observer = new MutationObserver((records) => {
      const target = this.getTarget();
      const wholeDocument = [...this.surfaces.keys()].some(
        (surface) => !target.contains(surface),
      );
      const relevant = records.filter((record) => {
        if (!relevantMutation(record)) return false;
        if (wholeDocument || target === document.body) return true;
        const ownsScope = (node: Node) =>
          node instanceof Element &&
          (node.getAttribute("data-glass-scope") === this.configuration.id ||
            [...node.querySelectorAll("[data-glass-scope]")].some(
              (surface) =>
                surface.getAttribute("data-glass-scope") ===
                this.configuration.id,
            ));
        if (
          (record.type === "childList" &&
            [...record.addedNodes, ...record.removedNodes].some(ownsScope)) ||
          (record.type === "attributes" &&
            (ownsScope(record.target) ||
              (record.attributeName === "data-glass-scope" &&
                record.oldValue === this.configuration.id)))
        )
          return true;
        if (target.contains(record.target)) return true;
        if (!record.target.contains(target)) return false;
        if (record.type !== "childList") return true;
        return [...record.addedNodes, ...record.removedNodes].some((node) =>
          node.contains(target),
        );
      });
      if (relevant.length) {
        const geometryOnly = relevant.every(geometryMutation);
        if (!geometryOnly) {
          this.materialsDirty = true;
          this.textContrast.invalidate();
          invalidateScene();
          this.scan();
        } else
          for (const record of relevant) {
            if (record.target instanceof HTMLElement) {
              const state = this.surfaces.get(record.target);
              if (state) state.edgeDirty = true;
            }
          }
        for (const record of relevant) {
          if (
            record.type !== "attributes" ||
            record.attributeName !== "data-glass-motion" ||
            !(record.target instanceof HTMLElement) ||
            !this.surfaces.has(record.target)
          )
            continue;
          if (record.target.dataset.glassMotion === "true") {
            this.moving.set(record.target, performance.now() + 3000);
            this.drawMotion();
          } else this.moving.delete(record.target);
        }
        this.schedule(false, geometryOnly);
      }
    });
    this.scan();
    this.observer.observe(document.documentElement, {
      attributes: true,
      attributeOldValue: true,
      attributeFilter: [
        "class",
        "style",
        "hidden",
        "inert",
        "data-glass",
        "data-glass-scope",
        "data-glass-intensity",
        "data-glass-frozen",
        "data-glass-motion",
        "data-glass-contrast",
        "data-color",
        "data-state",
        "data-open",
        "data-closed",
        "aria-pressed",
        "data-pressed",
        "aria-checked",
        "data-checked",
        "data-unchecked",
        "aria-selected",
        "data-selected",
        "data-active",
        "data-highlighted",
        "aria-invalid",
        "data-invalid",
        "disabled",
        "aria-hidden",
        "aria-busy",
        "placeholder",
        "value",
        "type",
        "readonly",
        "open",
        "aria-disabled",
        "data-disabled",
      ],
      childList: true,
      subtree: true,
      characterData: true,
    });
    const scroll = () => {
      invalidateScene();
      this.schedule(true);
    };
    const update = () => {
      this.materialsDirty = true;
      this.textContrast.invalidate();
      invalidateScene();
      this.schedule();
    };
    const visibility = () => {
      if (document.hidden && this.timer) {
        clearTimeout(this.timer);
        this.timer = undefined;
      } else if (!document.hidden) this.schedule();
    };
    window.addEventListener("scroll", scroll, { capture: true, passive: true });
    window.addEventListener("resize", update);
    document.addEventListener("input", update, true);
    document.addEventListener("change", update, true);
    document.addEventListener("load", update, true);
    document.addEventListener("visibilitychange", visibility);
    document.fonts?.addEventListener("loadingdone", update);
    const interaction = (event: Event) => {
      const target = event.target;
      if (
        target instanceof Element &&
        [...this.surfaces.keys()].some((surface) => surface.contains(target))
      )
        update();
    };
    for (const type of ["pointerover", "pointerout", "focusin", "focusout"])
      document.addEventListener(type, interaction, true);
    const appearance = window.matchMedia?.("(prefers-color-scheme: dark)");
    appearance?.addEventListener("change", update);
    const transition = (event: TransitionEvent) => {
      if (["color", "background-color", "opacity"].includes(event.propertyName))
        interaction(event);
      const target = event.target;
      if (
        !(target instanceof HTMLElement) ||
        !this.surfaces.has(target) ||
        !["translate", "transform", "width", "height"].includes(
          event.propertyName,
        )
      )
        return;
      if (
        event.type === "transitionrun" &&
        this.configuration.mode === "auto"
      ) {
        this.moving.set(target, performance.now() + 3000);
        this.drawMotion();
      } else if (event.type !== "transitionrun") {
        this.moving.delete(target);
        this.schedule(false, true);
      }
    };
    document.addEventListener("transitionrun", transition, true);
    document.addEventListener("transitionend", transition, true);
    document.addEventListener("transitioncancel", transition, true);
    this.removeListeners = () => {
      window.removeEventListener("scroll", scroll, true);
      window.removeEventListener("resize", update);
      document.removeEventListener("input", update, true);
      document.removeEventListener("change", update, true);
      document.removeEventListener("load", update, true);
      document.removeEventListener("visibilitychange", visibility);
      document.fonts?.removeEventListener("loadingdone", update);
      for (const type of ["pointerover", "pointerout", "focusin", "focusout"])
        document.removeEventListener(type, interaction, true);
      appearance?.removeEventListener("change", update);
      document.removeEventListener("transitionrun", transition, true);
      document.removeEventListener("transitionend", transition, true);
      document.removeEventListener("transitioncancel", transition, true);
    };
    this.schedule();
  }

  private drawMotion() {
    if (
      this.motionFrame ||
      this.disposed ||
      document.hidden ||
      this.configuration.mode !== "auto"
    )
      return;
    this.motionFrame = requestAnimationFrame(() => {
      this.motionFrame = 0;
      const now = performance.now();
      for (const [element, expiry] of this.moving)
        if (now >= expiry || !visible(element)) this.moving.delete(element);
      if (!this.moving.size) return;
      this.schedule(false, true);
      this.drawMotion();
    });
  }

  update(configuration: GlassConfiguration) {
    configuration = { ...configuration, mode: configuration.mode ?? "auto" };
    const previous = this.configuration;
    const same =
      previous.mode === configuration.mode &&
      previous.intensity === configuration.intensity &&
      previous.captureTarget === configuration.captureTarget &&
      (["strength", "blur", "tint", "tintOpacity", "highlight"] as const).every(
        (key) => previous.options?.[key] === configuration.options?.[key],
      );
    if (!same) {
      this.materialsDirty = true;
      this.configurationVersion++;
      this.textContrast.invalidate();
    }
    this.configuration = configuration;
    this.options = configuration.options ?? {};
    this.scan();
    if (configuration.mode !== "auto")
      for (const [element, state] of this.surfaces)
        this.restoreCss(element, state);
    this.schedule();
  }

  refreshDependency(background: HTMLElement) {
    if (
      this.disposed ||
      this.configuration.mode !== "auto" ||
      !visible(background)
    )
      return;
    const bounds = background.getBoundingClientRect();
    for (const [element] of this.surfaces) {
      if (
        element === background ||
        !visible(element) ||
        !overlaps(bounds, element.getBoundingClientRect())
      )
        continue;
      const target = this.getTarget();
      const captureTarget = target.contains(element) ? target : document.body;
      if (!captureTarget.contains(background)) continue;
      let blocked: Set<Element>;
      try {
        blocked = higherLayers(element);
      } catch {
        this.schedule();
        return;
      }
      if ([...blocked].some((item) => item.contains(background))) continue;
      this.schedule();
      return;
    }
  }

  refresh() {
    this.materialsDirty = true;
    this.textContrast.invalidate();
    this.schedule();
  }

  private scan() {
    const elements = new Set(
      [...document.querySelectorAll<HTMLElement>('[data-glass="true"]')].filter(
        (element) => element.dataset.glassScope === this.configuration.id,
      ),
    );
    for (const [element, state] of this.surfaces) {
      if (elements.has(element)) continue;
      this.resizeObserver.unobserve(element);
      this.intersectionObserver.unobserve(element);
      this.releaseFrame(element, state);
      this.surfaces.delete(element);
    }
    for (const element of elements) {
      const existing = this.surfaces.get(element);
      if (existing) continue;
      const state: SurfaceState = { base: "", tint: [0, 0, 0], opacity: 0 };
      this.surfaces.set(element, state);
      this.updateMaterial(element, state);
      element.dataset.glassState = "loading";
      this.resizeObserver.observe(element);
      this.intersectionObserver.observe(element);
    }
  }

  private updateMaterial(element: HTMLElement, state: SurfaceState) {
    const oldState = element.dataset.glassState;
    state.base = this.options.tint ?? nativeBackground(element);
    const tint = parseColor(state.base);
    state.tint = [tint[0], tint[1], tint[2]];
    state.opacity = clamp(
      this.options.tintOpacity,
      glassIntensityDefaults(element.dataset.glassIntensity).tintOpacity,
      0,
      1,
    );
    element.style.setProperty("--glass-base", state.base);
    this.updateEdge(element, state);
    const frameMaterial = JSON.stringify([
      state.base,
      state.opacity,
      element.style.getPropertyValue("--glass-blur"),
    ]);
    const materialKey = JSON.stringify([
      frameMaterial,
      element.style.getPropertyValue("--glass-edge"),
    ]);
    if (state.materialKey !== materialKey) {
      state.materialKey = materialKey;
      if (oldState === "ready" && state.frameMaterial !== frameMaterial) {
        this.restoreCss(element, state);
      }
      state.frameMaterial = frameMaterial;
      backgroundChanged(element);
    }
  }

  private restoreCss(
    element: HTMLElement,
    state: SurfaceState,
    status: "css" | "fallback" = "css",
  ) {
    const changed = Boolean(state.url || state.frameKey);
    if (state.url) URL.revokeObjectURL(state.url);
    state.url = undefined;
    state.frameKey = undefined;
    element.style.removeProperty("--glass-frame");
    element.dataset.glassState = status;
    if (changed) backgroundChanged(element);
  }

  private updateEdge(element: HTMLElement, state: SurfaceState) {
    state.edgeDirty = false;
    const defaults = glassIntensityDefaults(element.dataset.glassIntensity);
    element.style.setProperty(
      "--glass-blur",
      `${clamp(this.options.blur, defaults.blur, 0, 24)}px`,
    );
    element.style.setProperty(
      "--glass-opacity",
      `${clamp(this.options.tintOpacity, defaults.tintOpacity, 0, 1) * 100}%`,
    );
    const rect = element.getBoundingClientRect();
    const style = getComputedStyle(element);
    const radii = surfaceRadii(element, rect, style);
    const highlight = clamp(this.options.highlight, 0.3, 0, 1);
    const color = parseColor(
      style.getPropertyValue("--foreground").trim() || style.color,
    );
    const key = JSON.stringify([
      rect.width,
      rect.height,
      radii,
      highlight,
      color,
    ]);
    if (state.edgeKey === key) return;
    state.edgeKey = key;
    element.style.setProperty(
      "--glass-initial-edge-shadow",
      glassShadow(highlight),
    );
    element.style.setProperty(
      "--glass-edge",
      glassEdge(rect.width, rect.height, radii, highlight, color),
    );
  }

  schedule(scrolling = false, realtime = false) {
    if (this.disposed || document.hidden) return;
    this.dirty = true;
    this.scrollingDirty ||= scrolling;
    if (this.timer || this.queued) return;
    let delay = 0;
    if (!realtime)
      delay = Math.max(
        0,
        (scrolling ? 100 : 200) - (performance.now() - this.lastCapture),
      );
    this.timer = setTimeout(() => {
      this.timer = undefined;
      if (this.disposed || document.hidden) return;
      this.queued = true;
      queue = queue
        .then(() => this.capture())
        .catch(() => this.fallback())
        .finally(() => {
          this.queued = false;
          if (this.dirty && !this.disposed)
            this.schedule(false, this.moving.size > 0);
        });
    }, delay);
  }

  private getTarget() {
    const target = this.configuration.captureTarget;
    if (target && "current" in target) return target.current ?? document.body;
    return target ?? document.body;
  }

  private async capture() {
    if (this.disposed || document.hidden) return;
    this.dirty = false;
    const snapshotInterval = this.scrollingDirty ? 100 : 200;
    this.scrollingDirty = false;
    this.lastCapture = performance.now();
    const configurationVersion = this.configurationVersion;
    const capturedRevision = sceneRevision;
    this.scan();
    const active = [...this.surfaces].filter(([element]) => visible(element));
    if (!active.length) return;
    if (this.materialsDirty) {
      this.materialsDirty = false;
      for (const [element, state] of active)
        this.updateMaterial(element, state);
    } else {
      for (const [element, state] of active)
        if (state.edgeDirty || this.moving.has(element))
          this.updateEdge(element, state);
    }
    if (
      this.configuration.mode !== "auto" ||
      window.matchMedia?.(
        "(prefers-reduced-transparency: reduce), (forced-colors: active)",
      ).matches
    ) {
      for (const [element, state] of active) {
        this.restoreCss(element, state);
      }
      return;
    }
    const current = (element?: HTMLElement, state?: SurfaceState) =>
      !this.disposed &&
      !document.hidden &&
      this.configurationVersion === configurationVersion &&
      sceneRevision === capturedRevision &&
      (!element ||
        (visible(element) &&
          element.dataset.glass === "true" &&
          element.dataset.glassScope === this.configuration.id &&
          this.surfaces.get(element) === state));
    if (!current()) return;
    if (!renderer) {
      const controller = new AbortController();
      initialization = controller;
      try {
        const { GlassRenderer: Renderer } = await import("@/lib/glass/renderer");
        const created = await Renderer.create(controller.signal);
        if (!managers.size) {
          created.destroy();
          return;
        }
        renderer = created;
      } finally {
        if (initialization === controller) initialization = undefined;
      }
    }
    if (!current()) return;
    const target = this.getTarget();
    const peers = [
      ...document.querySelectorAll<HTMLElement>('[data-glass="true"]'),
    ].filter(visible);
    for (const [element, state] of active) {
      if (element.dataset.glassFrozen === "true") continue;
      if (!current(element, state)) continue;
      const rect = element.getBoundingClientRect();
      const style = getComputedStyle(element);
      let blocked: Set<Element>;
      try {
        blocked = higherLayers(element);
      } catch {
        if (!state.url) element.dataset.glassState = "fallback";
        continue;
      }
      // Disjoint peers cannot contribute to each other's background: omit them in the shared capture.
      for (const peer of peers) {
        const peerRect = peer.getBoundingClientRect();
        if (
          peer === element ||
          (!peer.contains(element) &&
            !element.contains(peer) &&
            (peerRect.right <= rect.left ||
              peerRect.left >= rect.right ||
              peerRect.bottom <= rect.top ||
              peerRect.top >= rect.bottom))
        )
          blocked.add(peer);
      }
      const captureTarget = target.contains(element) ? target : document.body;
      const captureDocument = captureTarget.ownerDocument;
      if (!this.captureFonts.has(captureDocument))
        this.captureFonts.set(
          captureDocument,
          acquireGlassCaptureFonts(captureDocument),
        );
      const exclusions = [...blocked]
        .filter((candidate) => captureTarget.contains(candidate))
        .filter(
          (candidate) =>
            ![...blocked].some(
              (parent) => parent !== candidate && parent.contains(candidate),
            ),
        )
        .map(idFor)
        .sort((a, b) => (a ?? 0) - (b ?? 0))
        .join(",");
      const dependencyKey = () =>
        peers
          .filter(
            (peer) =>
              captureTarget.contains(peer) &&
              ![...blocked].some((item) => item.contains(peer)),
          )
          .map((peer) => `${idFor(peer)}:${backgroundVersions.get(peer) ?? 0}`)
          .sort()
          .join(",");
      const dependencies = dependencyKey();
      const currentFrame = () => {
        if (
          element.dataset.glassFrozen === "true" ||
          !current(element, state) ||
          dependencies !== dependencyKey()
        )
          return false;
        const latest = element.getBoundingClientRect();
        if (
          latest.left !== rect.left ||
          latest.top !== rect.top ||
          latest.width !== rect.width ||
          latest.height !== rect.height
        ) {
          // Layout and compositor movement need not mutate the surface's DOM.
          // Keep its displayed frame while a fresh frame uses the new geometry.
          this.schedule(false, true);
          return false;
        }
        return true;
      };
      const key = `${exclusions}|${dependencies}`;
      let cached = sharedSnapshots.get(captureTarget);
      if (!cached || cached.revision !== sceneRevision) {
        cached = { revision: sceneRevision, frames: new Map() };
        sharedSnapshots.set(captureTarget, cached);
      }
      let snapshot = cached.frames.get(key);
      if (!snapshot) {
        const delay = snapshotInterval - (performance.now() - lastSnapshotTime);
        if (delay > 0)
          await new Promise((resolve) => setTimeout(resolve, delay));
        if (!currentFrame()) return;
        lastSnapshotTime = performance.now();
        try {
          snapshot = await captureGlassBackground(captureTarget, blocked);
        } catch {
          if (current(element, state) && !state.url)
            element.dataset.glassState = "fallback";
          continue;
        }
        if (!current(element, state) || dependencies !== dependencyKey())
          return;
        if (cached.frames.size >= 4) cached.frames.clear();
        cached.frames.set(key, snapshot);
      }
      if (!currentFrame()) continue;
      const strength = clamp(this.options.strength, 22, 0, 64);
      const tint = parseColor(this.options.tint ?? state.base);
      const foreground = parseColor(style.color);
      const corners = glassRadii(
        rect.width,
        rect.height,
        surfaceRadii(element, rect, style),
      );
      const surfaceContrast = element.dataset.glassContrast === "surface";
      const frame = {
        width: rect.width,
        height: rect.height,
        margin: 0,
        origin: [rect.left, rect.top],
        radius: [corners[0].x, corners[1].x, corners[2].x, corners[3].x],
        radiusY: [corners[0].y, corners[1].y, corners[2].y, corners[3].y],
        strength,
        blur: clamp(
          this.options.blur,
          glassIntensityDefaults(element.dataset.glassIntensity).blur,
          0,
          24,
        ),
        tint: [tint[0], tint[1], tint[2]],
        tintOpacity: state.opacity,
        foreground: [foreground[0], foreground[1], foreground[2]],
        textColors: surfaceContrast
          ? undefined
          : this.textContrast.read(element),
        textBounds: surfaceContrast
          ? undefined
          : this.textContrast.readBounds(element),
        minimumContrast:
          element.getAttribute("aria-hidden") === "true" ? 0 : 4.5,
      } satisfies Parameters<GlassRenderer["render"]>[1];
      const frameKey = `${idFor(snapshot)}:${JSON.stringify(frame)}`;
      if (state.frameKey === frameKey && state.url) continue;
      let blob: Blob;
      try {
        blob = await renderer.render(snapshot, frame);
      } catch (error) {
        if (!(error instanceof GlassContrastError)) throw error;
        if (currentFrame()) this.restoreCss(element, state, "fallback");
        continue;
      }
      if (!currentFrame()) continue;
      const url = URL.createObjectURL(blob);
      const image = new window.Image();
      this.pendingFrames.set(url, image);
      image.src = url;
      try {
        await image.decode();
      } catch {
        if (this.pendingFrames.delete(url)) URL.revokeObjectURL(url);
        if (currentFrame() && !state.url)
          element.dataset.glassState = "fallback";
        continue;
      }
      if (!this.pendingFrames.delete(url)) continue;
      if (!currentFrame()) {
        URL.revokeObjectURL(url);
        continue;
      }
      const previous = state.url;
      state.url = url;
      element.style.setProperty("--glass-frame", `url("${url}")`);
      element.dataset.glassState = "ready";
      if (previous) URL.revokeObjectURL(previous);
      if (state.frameKey !== frameKey) {
        state.frameKey = frameKey;
        backgroundChanged(element);
      }
    }
  }

  private fallback() {
    for (const [element, state] of this.surfaces)
      this.restoreCss(element, state, "fallback");
  }

  private releaseFrame(element: HTMLElement, state: SurfaceState) {
    if (state.url) URL.revokeObjectURL(state.url);
    element.style.removeProperty("--glass-frame");
    element.style.removeProperty("--glass-edge");
    element.style.removeProperty("--glass-initial-edge-shadow");
    element.style.removeProperty("--glass-blur");
    element.style.removeProperty("--glass-opacity");
    element.style.removeProperty("--glass-base");
    delete element.dataset.glassState;
  }

  destroy() {
    this.disposed = true;
    if (this.timer) clearTimeout(this.timer);
    if (this.motionFrame) cancelAnimationFrame(this.motionFrame);
    this.moving.clear();
    for (const [url, image] of this.pendingFrames) {
      image.src = "";
      URL.revokeObjectURL(url);
    }
    this.pendingFrames.clear();
    for (const release of this.captureFonts.values()) release();
    this.captureFonts.clear();
    this.observer.disconnect();
    this.resizeObserver.disconnect();
    this.intersectionObserver.disconnect();
    this.removeListeners();
    for (const [element, state] of this.surfaces)
      this.releaseFrame(element, state);
    this.surfaces.clear();
  }
}

export function acquireGlass(configuration?: GlassConfiguration) {
  const resolved = configuration ?? { id: "default" };
  let manager = managers.get(resolved.id);
  if (!manager) {
    manager = new GlassManager(resolved);
    managers.set(resolved.id, manager);
  } else if (
    "mode" in resolved ||
    "intensity" in resolved ||
    "options" in resolved ||
    "captureTarget" in resolved
  )
    manager.update(resolved);
  manager.leases++;
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (--manager.leases > 0) return;
    manager.destroy();
    managers.delete(resolved.id);
    if (!managers.size) {
      sharedSnapshots = new WeakMap();
      initialization?.abort();
      renderer?.destroy();
      renderer = undefined;
    }
  };
}

export function refreshGlass(id: string) {
  invalidateScene();
  managers.get(id)?.refresh();
}

export function updateGlassConfiguration(configuration: GlassConfiguration) {
  managers.get(configuration.id)?.update(configuration);
}

